using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace EFCorePerformanceDemo
{
    // ===== 实体定义 =====
    public class User
    {
        public int Id { get; set; }
        public string Name { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public bool IsActive { get; set; } = true;
        public bool IsDeleted { get; set; }
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public DateTime? DeletedAt { get; set; }
        public ICollection<Order> Orders { get; set; } = new List<Order>();
    }

    public class Order
    {
        public int Id { get; set; }
        public string ProductName { get; set; } = string.Empty;
        public decimal Price { get; set; }
        public int Quantity { get; set; }
        public DateTime OrderDate { get; set; } = DateTime.UtcNow;
        public int UserId { get; set; }
        public User User { get; set; } = null!;
    }

    public class UserDto
    {
        public int Id { get; set; }
        public string Name { get; set; } = string.Empty;
        public int OrderCount { get; set; }
        public decimal TotalSpent { get; set; }
    }

    // ===== DbContext =====
    public class AppDbContext : DbContext
    {
        public DbSet<User> Users => Set<User>();
        public DbSet<Order> Orders => Set<Order>();

        public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<User>(e =>
            {
                e.HasIndex(u => u.Email).IsUnique();
                e.HasIndex(u => u.IsActive);
            });
            modelBuilder.Entity<Order>(e =>
            {
                e.HasIndex(o => o.UserId);
            });
        }
    }

    public static class Demos
    {
        /// <summary>
        /// Demo 1: N+1 问题 vs Include vs 投影
        /// </summary>
        public static async Task NPlus1Demo(AppDbContext db, ILogger logger)
        {
            // --- N+1: 遍历时触发懒加载或手动查询 ---
            var sw = Stopwatch.StartNew();
            var users = await db.Users.AsNoTracking().ToListAsync();
            foreach (var user in users)
            {
                // 每次循环发一条 SQL: SELECT ... FROM Orders WHERE UserId = @p0
                user.Orders = await db.Orders
                    .Where(o => o.UserId == user.Id)
                    .ToListAsync();
            }
            sw.Stop();
            logger.LogInformation("N+1 方式: {Count} 用户, {Ms}ms, {Queries} 条查询",
                users.Count, sw.ElapsedMilliseconds, users.Count + 1);

            // --- Include: 一条 JOIN 搞定 ---
            sw.Restart();
            var usersWithOrders = await db.Users
                .AsNoTracking()
                .Include(u => u.Orders)
                .ToListAsync();
            sw.Stop();
            logger.LogInformation("Include 方式: {Count} 用户, {Ms}ms, 1 条查询",
                usersWithOrders.Count, sw.ElapsedMilliseconds);

            // --- 投影: 只取需要的字段 ---
            sw.Restart();
            var dtos = await db.Users
                .Select(u => new UserDto
                {
                    Id = u.Id,
                    Name = u.Name,
                    OrderCount = u.Orders.Count,
                    TotalSpent = u.Orders.Sum(o => o.Price * o.Quantity)
                })
                .ToListAsync();
            sw.Stop();
            logger.LogInformation("投影方式: {Count} 用户, {Ms}ms, 1 条查询, 无 ChangeTracker 开销",
                dtos.Count, sw.ElapsedMilliseconds);
        }

        /// <summary>
        /// Demo 2: AsNoTracking vs 默认跟踪 的内存差异
        /// </summary>
        public static async Task TrackingOverheadDemo(AppDbContext db, ILogger logger)
        {
            // 默认跟踪: 每个实体做快照 + 入 Identity Resolution 字典
            var sw = Stopwatch.StartNew();
            var tracked = await db.Users
                .Where(u => u.IsActive)
                .ToListAsync();
            sw.Stop();
            logger.LogInformation("跟踪模式: {Count} 条, {Ms}ms (含快照和 Identity Resolution)",
                tracked.Count, sw.ElapsedMilliseconds);

            // AsNoTracking: 跳过快照和 Identity Resolution
            db.ChangeTracker.Clear(); // 清除之前的跟踪
            sw.Restart();
            var noTracking = await db.Users
                .AsNoTracking()
                .Where(u => u.IsActive)
                .ToListAsync();
            sw.Stop();
            logger.LogInformation("NoTracking: {Count} 条, {Ms}ms (无快照开销)",
                noTracking.Count, sw.ElapsedMilliseconds);
        }

        /// <summary>
        /// Demo 3: EF Core 7+ ExecuteUpdate/ExecuteDelete 批量操作
        /// </summary>
        public static async Task BulkOperationsDemo(AppDbContext db, ILogger logger)
        {
            var cutoff = DateTime.UtcNow.AddDays(-30);

            // 传统方式: 查出实体 → 逐条修改 → SaveChanges (N 条 UPDATE)
            // var oldUsers = await db.Users.Where(u => u.CreatedAt < cutoff && u.IsActive).ToListAsync();
            // oldUsers.ForEach(u => u.IsActive = false);
            // await db.SaveChangesAsync(); // 生成 N 条 UPDATE 语句

            // EF Core 7+: 一条 UPDATE 搞定
            var sw = Stopwatch.StartNew();
            int affected = await db.Users
                .Where(u => u.CreatedAt < cutoff && u.IsActive)
                .ExecuteUpdateAsync(s => s
                    .SetProperty(u => u.IsActive, false));
            sw.Stop();
            logger.LogInformation("ExecuteUpdate: 影响 {Affected} 行, {Ms}ms, 1 条 SQL",
                affected, sw.ElapsedMilliseconds);

            // 批量删除: 一条 DELETE
            sw.Restart();
            int deleted = await db.Users
                .Where(u => !u.IsActive && u.IsDeleted)
                .ExecuteDeleteAsync();
            sw.Stop();
            logger.LogInformation("ExecuteDelete: 删除 {Deleted} 行, {Ms}ms, 1 条 SQL",
                deleted, sw.ElapsedMilliseconds);
        }

        /// <summary>
        /// Demo 4: Any vs Count
        /// </summary>
        public static async Task AnyVsCountDemo(AppDbContext db)
        {
            // Any: EXISTS → 找到第一条就返回
            bool hasActive = await db.Users.AnyAsync(u => u.IsActive);

            // Count: COUNT(*) → 必须扫描所有匹配行
            // bool hasActiveBad = await db.Users.CountAsync(u => u.IsActive) > 0;

            Console.WriteLine($"Has active users: {hasActive}");
        }
    }
}
